    /**
     * Tests getting all LineageNodes.
     *
     * @return    Collection
     */
    public List<LineageNode> testGetAll() throws Throwable {
    LOGGER.info( "LineageNodeTest:testGetAll() - Retrieving Collection of LineageNodes:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all LineageNode : " );
    List<LineageNode> collection  = null;

    try {
        // call the static get method on the LineageNodeService
        collection = service.getAllLineageNode();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            LineageNode currEntity  = null;
            Iterator<LineageNode> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getLineageNodeId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

